#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# Task 478: обновление системного промта (post-478) — карточка
# прибора КИП ИОС: строка «Период ремонта» цветная по состоянию
# ППР (зелёный/красный/обычный); SW v701→v702; тесты 5630/0.
import io
import sys

PATH = 'Системный_промт_для_приложения_КИПиА.md'
with io.open(PATH, encoding='utf-8') as f:
    src = f.read()

CUR_MARK = '> **Версия документа:** 2026-10-04 (post-Task 475-477 ПЕРЕНОС: партия ЭТАПОВ 1-3 ОПТИМИЗАЦИИ перен'
PREV_MARK = '> **Версия документа (предыдущая):**'

NEW_LINE3 = '> **Версия документа:** 2026-10-06 (post-Task 478: КАРТОЧКА ПРИБОРА КИП ИОС — ЦВЕТ СТРОКИ «ПЕРИОД РЕМОНТА» ПО СОСТОЯНИЮ ППР. Заявка пользователя: «В разделе КИП ИОС, в подробных карточках приборов текст в строке с датой периода ремонта нужно окрашивать в зелёный или красный цвета по условиям. Если прибор есть в графике ППР, и если вид ремонта у него "ТО" или вид ремонта "К" или "П" и дата ремонта не просрочена в зависимости от периода ремонта и текущей даты, то цвет текста зелёный, если есть в ППР и дата ремонта просрочена - красным, остальные не по этим условиям обычный цвет». РЕАЛИЗАЦИЯ (КЛИЕНТ-ONLY, Apps Script не тронут, данные не менялись): (а) НОВАЯ функция devPprStatusClass(dev, nowOpt) в index.html перед devRenderDetail — возвращает CSS-класс строки «Период ремонта»: dev-ppr-ok (ЗЕЛЁНЫЙ) — «В гр. ППР»=«Есть» (регистронезависимо) + «Вид ремонта» ТО/К/П + срок НЕ просрочен (дата последнего ремонта + период («(3 мес)»/«(1 год)»/«(2 года)»/«(5 лет)» и т.п.) >= сегодня); dev-ppr-bad (КРАСНЫЙ) — то же, но срок < сегодня; \'\' (обычный) — не в ППР / вид не ТО/К/П / срок не вычислить (нет даты/периода/неизвестная единица). Граница «сегодня» — лексикографическое сравнение ISO-строк (приём Task 380/444; срок ровно «сегодня» — ещё действует); дата «сегодня» инлайн (самодостаточность в мок-тестах); nowOpt — фиксированная «сегодня» для тестов; семантика JS Date auto-overflow (29.02+2 года → 01.03) задокументирована. На 2026-10-06: зелёный 643, красный 210, обычный 438. (б) devRenderDetail: в ветке isCombined (комбинированное поле __period__ = «Дата + Вид ремонта + Период ремонта», group 1) вычисляется pprCls и добавляется к классу ЗНАЧЕНИЯ .dev-card-value ((pprCls ? \' \' + pprCls : \'\')); метка строки и прочие строки карточки НЕ окрашиваются; десктоп-панель devRenderDetailInPanel рендерит тем же devRenderDetail (подмена контейнера) — индикация автоматически и на десктопе. (в) CSS: .dev-card-value.dev-ppr-ok #81c784 (светлая #2e7d32), .dev-ppr-bad #ef5350 (светлая #c62828), font-weight 600 — палитра строк следующих сроков инструктажей (Task 407 .ws-il-due-*), обе темы. sw.js kipia-test-v701→v702 + комментарий Task 478 (~340 симв., 6 строк); ЛОГИКИ SW НЕ МЕНЯЛОСЬ. Тесты 5630/0 (+44 к 5586): НОВЫЙ test-task478.js ×44 (CSS ×5, ветки условий ×6, периоды мес/год ×11 включая переход года/високосность/переполнение дня JS, граница «сегодня» ×6, интеграция ×6, ДАННЫЕ-инварианты ×5 — devices.json синкается кроном ежедневно, поэтому НЕ точные счётчики: ППР≠«Есть»→всегда обычный, предусловия→всегда ok|bad, monotonicity при росте «сегодня», обе ветки представлены; SW ×5). Бамп task478-bump-sw.py: guards v702→v703 (131) ПОСЛЕ ассертов v701→v702 (548), 162 файла, OWN исключён; ОКНА ИСТОРИИ sw.js расширены (прецедент Task 475/476): test-task461 5300→6000 (~5362), test-task471 2700→3400 (~2800), test-task472 2100→2900 (~2251) + 2700→3400, test-task474 1700→2500 (~1878) + дистанции, test-task475 — литералы чужих окон, test-task476/477 — дистанции. Браузер task478-browser-check.py 68/68 (порт 8989, мок Apps Script, ОЖИДАНИЯ ДИНАМИЧЕСКИЕ — эталонный статус тем же алгоритмом на дату запуска): десктоп 1280x900 тёмная/светлая + мобильный 375x812; тройка ID 1 (К, 2024-04-01+(6 лет)=2030 → ЗЕЛЁНЫЙ), ID 16 (ТО, 2026-01-15+(3 мес)=2026-04-15<сегодня → КРАСНЫЙ), ID 81 (ППР=Нет → ОБЫЧНЫЙ); computed colors точные; класс ровно на значении; метка/прочие строки не окрашены; fontWeight 600; 0 JS ×3; 5 скриншотов; VLM ×4 — цвета читаются однозначно, дефектов нет. ПОДВОДНЫЕ КАМЕНЬ: у ID 81 пустая «Позиция» — строка не рендерится (контрольная строка = первая прочая). DEPLOY-Task478-device-card-ppr-period-color.md (клиент-only, откат — вернуть файлы + поднять версию). ТЕКУЩЕЕ СОСТОЯНИЕ: kip8test SW `kipia-test-v702` (guard v703), тесты 5630/0; kip8 @5da84b8, SW `kipia-v510`, тесты 5592/0 — Task 478 ЖДУТ ПЕРЕНОСА В kip8 ПО КОМАНДЕ (одним инкрементом kipia-v510→v511; маппинг тестов v702→v511/v703→v512/негативы v701→v510 + окна истории). СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 479 (в обоих репо).'

if CUR_MARK not in src:
    print('ОШИБКА: не найдена строка версии post-475-477 ПЕРЕНОС')
    sys.exit(1)

# (а) удалить самую старую строку «предыдущая» (ПОСЛЕДНЯЯ по позиции —
# подводный камень из Task 475-477: rindex, не первая)
if src.count(PREV_MARK) > 2:
    iprev = src.rindex(PREV_MARK)
    iprev_end = src.index('\n', iprev)
    src = src[:iprev] + src[iprev_end + 1:]

i3 = src.index(CUR_MARK)
i3end = src.index('\n', i3)
old_line3 = src[i3:i3end]

# (б) строка 3 → новая версия + «предыдущая» из старой строки 3
new_prev = PREV_MARK + ' ' + old_line3[len('> **Версия документа:** '):]
src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) «Текущая версия кэша» v701 → v702
old_cache = '> **Текущая версия кэша:** `kipia-test-v701`'
new_cache = '> **Текущая версия кэша:** `kipia-test-v702`'
if old_cache not in src:
    print('ОШИБКА: не найдена строка текущей версии кэша')
    sys.exit(1)
src = src.replace(old_cache, new_cache, 1)

# (г) строка «Инкрементируй» — следующие версии
old_inc = 'Формат: `kipia-test-v701` → `kipia-test-v702` (для kip8test) или `kipia-v510` → `kipia-v511` (для kip8)'
new_inc = 'Формат: `kipia-test-v702` → `kipia-test-v703` (для kip8test) или `kipia-v510` → `kipia-v511` (для kip8)'
if old_inc not in src:
    print('ОШИБКА: не найдена строка «Инкрементируй»')
    sys.exit(1)
src = src.replace(old_inc, new_inc, 1)

# (д) ожидание тестов kip8test 5586 → 5630; kip8 5467 → 5592
# (5467 устарел после ПЕРЕНОСА Task 475-477 — kip8 теперь 5592)
old_exp = '# Ожидается: 5586 passed, 0 failed (kip8test; в kip8 — 5467 passed, 0 failed)'
new_exp = '# Ожидается: 5630 passed, 0 failed (kip8test; в kip8 — 5592 passed, 0 failed)'
if old_exp not in src:
    print('ОШИБКА: не найдена строка ожидания тестов')
    sys.exit(1)
src = src.replace(old_exp, new_exp, 1)

# проверки
checks = [
    ('post-Task 478', 1),
    ('kipia-test-v702', None),
    ('devPprStatusClass', None),
    ('5630 passed, 0 failed (kip8test', 1),
    ('СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 479', None),
    ('dev-ppr-ok', None),
    ('post-Task 475-477 ПЕРЕНОС', None),
]
for marker, cnt in checks:
    c = src.count(marker)
    if cnt is not None and c != cnt:
        print('ОШИБКА: маркер %r найден %d раз (ожидалось %s)' % (marker[:60], c, cnt))
        sys.exit(1)
    if cnt is None and c == 0:
        print('ОШИБКА: маркер не найден: %r' % marker[:60])
        sys.exit(1)

with io.open(PATH, 'w', encoding='utf-8') as f:
    f.write(src)

print('OK: промт обновлён post-Task 478 (SW v702, тесты 5630/0, следующий 479)')
